def median(xs: list[float]) -> float:
    """Median of a non-empty list. For even length, the mean of the two middle values."""
    xs_sorted = sorted(xs)
    n = len(xs_sorted)
    mid = n // 2
    if n % 2 == 1:
        return float(xs_sorted[mid])
    else:
        return (xs_sorted[mid - 1] + xs_sorted[mid]) / 2.0
